# ---- Write clean public/index.html (galaxy UI, verified UTF-8) ----
$indexB64 = ""
if (-not (Test-Path ".\public")) { New-Item -ItemType Directory -Path ".\public" | Out-Null }
[System.IO.File]::WriteAllBytes("$PWD\public\index.html", [System.Convert]::FromBase64String($indexB64))
Write-Host "Rewrote public\index.html: repaired corruption, full working app, galaxy theme" -ForegroundColor Green

# ---- Verify everything ----
Write-Host "`nVerifying every .js file's syntax..." -ForegroundColor Cyan
$failed = $false
Get-ChildItem -Path . -Recurse -Filter "*.js" -File | Where-Object { $_.FullName -notmatch "node_modules|\.git" } | ForEach-Object {
    $result = node --check $_.FullName 2>&1
    if ($LASTEXITCODE -ne 0) {
        Write-Host "SYNTAX ERROR in $($_.FullName):" -ForegroundColor Red
        Write-Host $result
        $failed = $true
    }
}
if (-not $failed) { Write-Host "All .js files: syntax OK" -ForegroundColor Green }

Write-Host "`nVerifying public/index.html inline scripts..." -ForegroundColor Cyan
node -e "const fs=require('fs');const html=fs.readFileSync('public/index.html','utf8');const m=[...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)];let ok=true;m.forEach((x,i)=>{if(x[1].trim().length){try{new Function(x[1])}catch(e){ok=false;console.log('Block '+i+' error: '+e.message)}}});console.log(ok?'index.html: all inline scripts OK':'index.html: ERRORS FOUND ABOVE')"

Write-Host "`nInstalling dependencies (this also removes now-unused packages)..." -ForegroundColor Cyan
if (Test-Path ".\package-lock.json") { Remove-Item ".\package-lock.json" -Force }
if (Test-Path ".\node_modules") { Remove-Item -Recurse -Force ".\node_modules" }
npm install

Write-Host "`n============================================================" -ForegroundColor Yellow
Write-Host "REMINDER: your .env file was left untouched." -ForegroundColor Yellow
Write-Host "Confirm it holds your ROTATED Mongo password and Gmail app" -ForegroundColor Yellow
Write-Host "password (not the old leaked ones) before you rely on this." -ForegroundColor Yellow
Write-Host "============================================================" -ForegroundColor Yellow

Write-Host "`nDone. Start your server with: npm start" -ForegroundColor Green
Write-Host "Demo logins printed in the console on first run:" -ForegroundColor Green
Write-Host "  admin@college.edu / password123"
Write-Host "  organizer@college.edu / password123"
Write-Host "  student1@college.edu / password123"